    const settle = reduce ? 1 : ease(clamp(local / 1.1));
    if (!reduce && local < 0.8) { if (flip) setGlyph(L, GLYPHS[Math.floor(Math.random() * GLYPHS.length)]); }
    else if (i === gi && flip) setGlyph(L, GLYPHS[Math.floor(Math.random() * GLYPHS.length)]);
    else if (i !== gi) setGlyph(L, L.ch);
